//! Closed-world acceleration of the exact battle-mode predicate. Immutable
//! configuration plans replace only transient pure split/parser work. Both
//! actual getDataTable calls and the conditional getBattleId call still run.
use crate::{Runtime,Value,StringId,ObjectId,ObjectKind,PropertyKey,Descriptor,PropertyKind,EnvId,JsResult};
use crate::closures::{FunctionKind,FunctionSource};
const ENGINE_GETTER_SOURCE:&str=include_str!("battle_mode_engine_getter_source.js");
const TABLE_SOURCE:&str=include_str!("battle_mode_get_table_source.js");
const ID_SOURCE:&str=include_str!("battle_mode_get_id_source.js");
const PARSER_SOURCE:&str=include_str!("battle_mode_parser_source.js");
pub(crate) struct BattleModeGuard{object:Value,properties:Vec<(ObjectId,PropertyKey,Option<Descriptor>)>}
pub(crate) struct BattleModePlan{stage:StringId,heroes:StringId,ranges:Vec<(StringId,u32,u32)>,hero_ids:Vec<u32>}
enum Raw{Missing,Value(Value),Unsafe}
fn same(a:Option<Descriptor>,b:Option<Descriptor>)->bool{match(a,b){(None,None)=>true,(Some(a),Some(b))=>a.enumerable==b.enumerable&&a.configurable==b.configurable&&match(a.kind,b.kind){(PropertyKind::Data{value:a,writable:aw},PropertyKind::Data{value:b,writable:bw})=>a==b&&aw==bw,_=>false},_=>false}}
fn exact_source(source:Option<&FunctionSource>,expected:&str)->bool{match source{Some(FunctionSource::Owned(s))=>s.iter().copied().eq(expected.encode_utf16()),Some(FunctionSource::StaticUtf16Le{bytes,start,end})=>bytes.get(start.saturating_mul(2)..end.saturating_mul(2)).is_some_and(|b|b.chunks_exact(2).map(|p|u16::from_le_bytes([p[0],p[1]])).eq(expected.encode_utf16())),_=>false}}
fn integer(v:Value)->Option<u32>{match v{Value::Number(n)if n.is_finite()&&n>=0.0&&n<=u32::MAX as f64&&n.fract()==0.0=>Some(n as u32),_=>None}}
impl Runtime {
 pub(crate) fn capture_battle_mode_guard(&mut self){let mut properties=Vec::new();let object_key=PropertyKey(self.intern("Object"));let Some(d)=self.objects[self.global_object.0].own(object_key)else{return};let PropertyKind::Data{value:object,..}=d.kind else{return};let Ok(object_id)=self.object_id(object)else{return};let has_key=PropertyKey(self.intern("hasOwnProperty"));let Some(has)=self.objects[self.object_prototype.0].own(has_key)else{return};let PropertyKind::Data{value:has,..}=has.kind else{return};let Ok(has_id)=self.object_id(has)else{return};for(object,name)in[(self.global_object,"Object"),(object_id,"prototype"),(self.object_prototype,"hasOwnProperty"),(self.function_prototype,"call"),(has_id,"call"),(self.string_prototype,"split")]{let key=PropertyKey(self.intern(name));properties.push((object,key,self.objects[object.0].own(key)));}self.battle_mode_guard=Some(BattleModeGuard{object,properties});}
 fn mode_raw_property(&self,value:Value,key:PropertyKey)->Raw{let Ok(mut id)=self.object_id(value)else{return Raw::Unsafe};for _ in 0..32{let Some(object)=self.objects.get(id.0)else{return Raw::Unsafe};if !matches!(object.kind,ObjectKind::Ordinary)||!object.arguments_map.is_empty(){return Raw::Unsafe}if let Some(d)=object.own(key){return match d.kind{PropertyKind::Data{value,..}=>Raw::Value(value),_=>Raw::Unsafe}}if let Some(parent)=object.prototype{id=parent}else{return Raw::Missing}}Raw::Unsafe}
 fn mode_raw_binding(&self,mut env:EnvId,name:StringId)->Raw{loop{let Some(e)=self.environments.get(env.0)else{return Raw::Unsafe};if let Some(&slot)=e.bindings.get(&name){let Some(b)=e.cells.get(slot)else{return Raw::Unsafe};if !b.alive||!b.initialized{return Raw::Unsafe}if !b.object_backed{return Raw::Value(b.value)}break}if let Some(parent)=e.parent{env=parent}else{break}}self.mode_raw_property(Value::Object(self.global_object),PropertyKey(name))}
 fn mode_value(&mut self,value:Value,name:&'static str)->Option<Value>{let key=PropertyKey(self.static_identifier_id(name));match self.mode_raw_property(value,key){Raw::Value(v)=>Some(v),_=>None}}
 fn mode_source_env(&self,value:Value,source:&str)->Option<EnvId>{let Value::Function(id)=value else{return None};let f=self.functions.get(id.0)?;if !exact_source(f.source.as_ref(),source){return None}match f.kind{FunctionKind::Native{env,..}=>Some(env),_=>None}}
 fn mode_helpers_intact(&self)->bool{let Some(g)=&self.battle_mode_guard else{return false};for &(object,key,expected)in &g.properties{if !same(self.objects[object.0].own(key),expected){return false}}if self.objects[self.function_prototype.0].prototype!=Some(self.object_prototype)||self.objects[self.string_prototype.0].prototype!=Some(self.object_prototype){return false}let has_key=g.properties[2].1;let Some(Descriptor{kind:PropertyKind::Data{value:has,..},..})=self.objects[self.object_prototype.0].own(has_key)else{return false};let Ok(id)=self.object_id(has)else{return false};self.objects[id.0].prototype==Some(self.function_prototype)&&!self.objects[self.object_prototype.0].iter_properties().any(|(_,d)|d.enumerable)}
 fn mode_engine(&mut self,ed:Value)->Option<(Value,Option<Value>)>{
  let id=self.object_id(ed).ok()?;let key=PropertyKey(self.static_identifier_id("battleEngine"));let object=self.objects.get(id.0)?;
  if !matches!(object.kind,ObjectKind::Ordinary)||!object.arguments_map.is_empty(){return None}
  if let Some(Descriptor{kind:PropertyKind::Accessor{get:Some(getter),..},..})=object.own(key){
   if object.prototype!=Some(self.object_prototype)||self.mode_source_env(getter,ENGINE_GETTER_SOURCE).is_none(){return None}
   let instance=PropertyKey(self.static_identifier_id("_battleEngineInstance"));let Some(Descriptor{kind:PropertyKind::Data{value:Value::Object(engine),..},..})=self.objects[id.0].own(instance)else{return None};
   return Some((Value::Object(engine),Some(getter)))
  }
  self.mode_value(ed,"battleEngine").map(|engine|(engine,None))
 }
 fn mode_invoke_getter(&mut self,getter:Value,ed:Value,engine:Value)->JsResult<()>{self.battle_mode_limit_getter_calls=self.battle_mode_limit_getter_calls.wrapping_add(1);let actual=self.call(getter,ed,&[])?;debug_assert_eq!(actual,engine);Ok(())}
 pub fn try_native_battle_mode_limit(&mut self,hero:Value,parent:EnvId)->JsResult<Option<Value>>{
  if !self.native_battle_mode_limit_enabled{return Ok(None)}self.battle_mode_limit_attempts=self.battle_mode_limit_attempts.wrapping_add(1);if !self.truthy(hero){self.battle_mode_limit_hits=self.battle_mode_limit_hits.wrapping_add(1);return Ok(Some(Value::Bool(false)))}
  if !self.mode_helpers_intact(){return Ok(None)}
  let ed_name=self.static_identifier_id("ed");let Raw::Value(ed)=self.mode_raw_binding(parent,ed_name)else{return Ok(None)};
  let Some((engine,engine_getter))=self.mode_engine(ed)else{return Ok(None)};let Some(config)=self.mode_value(engine,"config")else{return Ok(None)};let Some(Value::String(mode))=self.mode_value(config,"mode")else{return Ok(None)};if self.string_units(mode).is_empty(){return Ok(None)}
  let Some(table_fn)=self.mode_value(ed,"getDataTable")else{return Ok(None)};let Some(table_env)=self.mode_source_env(table_fn,TABLE_SOURCE)else{return Ok(None)};
  let Some(parser)=self.mode_value(ed,"parseUseSkillCacheStageBattle")else{return Ok(None)};let Some(parser_env)=self.mode_source_env(parser,PARSER_SOURCE)else{return Ok(None)};if !self.stage_range_intrinsics_intact(parser_env){return Ok(None)}
  let object_name=self.static_identifier_id("Object");let Raw::Value(object)=self.mode_raw_binding(table_env,object_name)else{return Ok(None)};if object!=self.battle_mode_guard.as_ref().unwrap().object{return Ok(None)}
  let tables_name=self.static_identifier_id("__nativeTables");let Raw::Value(tables)=self.mode_raw_binding(table_env,tables_name)else{return Ok(None)};
  let boundary_name=self.static_identifier_id("__nativeTableBoundary");if !matches!(self.mode_raw_binding(table_env,boundary_name),Raw::Missing|Raw::Value(Value::Undefined)){return Ok(None)}
  let Some(param)=self.mode_value(tables,"Param")else{return Ok(None)};let param_key=PropertyKey(self.static_identifier_id("Param"));let Ok(tables_id)=self.object_id(tables)else{return Ok(None)};if !matches!(self.objects[tables_id.0].own(param_key),Some(Descriptor{kind:PropertyKind::Data{value,..},..})if value==param){return Ok(None)}
  let Some(stage)=self.mode_value(param,"Stage")else{return Ok(None)};let Some(stage_row)=self.mode_value(stage,"UseSkillCacheStageBattle")else{return Ok(None)};let Some(Value::String(stage_text))=self.mode_value(stage_row,"StrValue")else{return Ok(None)};
  let Some(hero_row)=self.mode_value(stage,"UseSkillCacheHeroList")else{return Ok(None)};let Some(Value::String(hero_text))=self.mode_value(hero_row,"StrValue")else{return Ok(None)};
  let Some(info)=self.mode_value(hero,"info")else{return Ok(None)};let Some(hero_id)=self.mode_value(info,"ID").and_then(integer)else{return Ok(None)};
  let Some(camp)=self.mode_value(hero,"camp").and_then(integer)else{return Ok(None)};let Some(camps)=self.mode_value(ed,"battle_camp")else{return Ok(None)};let Some(enemy)=self.mode_value(camps,"enemy").and_then(integer)else{return Ok(None)};
  if !self.battle_mode_plan.as_ref().is_some_and(|p|p.stage==stage_text&&p.heroes==hero_text){
   let units=self.string_units(stage_text);if units.len()>8192{return Ok(None)}let parts=units.split(|u|*u==59).collect::<Vec<_>>();if parts.len()>128{return Ok(None)}let mut raw:Vec<(Vec<u16>,u32,u32)>=Vec::new();let mut current:Option<&[u16]>=None;let mut i=0;
   while i<parts.len(){if let Some(lo)=crate::stage_range_parser::uint(parts[i]){let Some(name)=current else{return Ok(None)};let Some(next)=parts.get(i+1)else{return Ok(None)};let Some(hi)=crate::stage_range_parser::uint(next)else{return Ok(None)};raw.push((name.to_vec(),lo,hi));i+=2;}else if crate::stage_range_parser::mode(parts[i]){current=Some(parts[i]);i+=1;}else{return Ok(None)}}
   let hu=self.string_units(hero_text);if hu.len()>4096{return Ok(None)}let mut hero_ids=Vec::new();for token in hu.split(|u|*u==59){let Some(id)=crate::stage_range_parser::uint(token)else{return Ok(None)};if hero_ids.len()>=128{return Ok(None)}hero_ids.push(id)}hero_ids.sort_unstable();hero_ids.dedup();
   let mut ranges=Vec::new();for(name,lo,hi)in raw{let name=self.intern_utf16(&name);ranges.push((name,lo,hi));}self.battle_mode_plan=Some(BattleModePlan{stage:stage_text,heroes:hero_text,ranges,hero_ids});
  }
  let plan=self.battle_mode_plan.as_ref().unwrap();for &(name,_,_)in &plan.ranges{if self.objects[self.object_prototype.0].own(PropertyKey(name)).is_some(){return Ok(None)}}
  let match_mode=plan.ranges.iter().any(|(name,_,_)|*name==mode);
  let mut battle_fn=None;if match_mode{let Some(f)=self.mode_value(engine,"getBattleId")else{return Ok(None)};if self.mode_source_env(f,ID_SOURCE).is_none(){return Ok(None)}if self.mode_value(engine,"battle_id").and_then(integer).is_none(){return Ok(None)}battle_fn=Some(f);}
  // All reads, source identities and primitive domains are validated before
  // the first source call. The proven helper paths cannot mutate any inputs.
  if let Some(getter)=engine_getter{self.mode_invoke_getter(getter,ed,engine)?;self.mode_invoke_getter(getter,ed,engine)?;}
  let param_name=self.static_string("Param");let actual=self.call(table_fn,ed,&[param_name])?;debug_assert_eq!(actual,param);
  let range_matches=if let Some(f)=battle_fn{if let Some(getter)=engine_getter{self.mode_invoke_getter(getter,ed,engine)?;}let id=self.call(f,engine,&[])?;let id=integer(id).expect("validated pure battle ID");self.battle_mode_plan.as_ref().unwrap().ranges.iter().any(|&(name,lo,hi)|name==mode&&id>=lo&&id<=hi)}else{false};
  let actual=self.call(table_fn,ed,&[param_name])?;debug_assert_eq!(actual,param);
  let hero_matches=self.battle_mode_plan.as_ref().unwrap().hero_ids.binary_search(&hero_id).is_ok();self.battle_mode_limit_domain_hits=self.battle_mode_limit_domain_hits.wrapping_add(1);self.battle_mode_limit_hits=self.battle_mode_limit_hits.wrapping_add(1);Ok(Some(Value::Bool(match_mode&&range_matches&&hero_matches&&camp==enemy)))
 }
}
impl BattleModeGuard{pub(crate)fn reachability_roots(&self)->Vec<Value>{let mut out=vec![self.object];for &(object,key,d)in &self.properties{out.push(Value::Object(object));out.push(Value::String(key.0));if let Some(Descriptor{kind:PropertyKind::Data{value,..},..})=d{out.push(value)}}out}}
impl BattleModePlan{pub(crate)fn reachability_roots(&self)->Vec<Value>{let mut out=vec![Value::String(self.stage),Value::String(self.heroes)];out.extend(self.ranges.iter().map(|(name,_,_)|Value::String(*name)));out}}
#[cfg(test)]mod tests{
 use super::*;use std::cell::Cell;
 thread_local!{static CALLS:Cell<(usize,usize)>=const{Cell::new((0,0))};static ORDER:std::cell::RefCell<Vec<u8>>=const{std::cell::RefCell::new(Vec::new())};}
 fn set(rt:&mut Runtime,o:Value,k:&str,v:Value){let k=rt.string(k);rt.define_data(o,k,v,true,true,true).unwrap();}
 fn table(rt:&mut Runtime,_:Value,_:&[Value],parent:EnvId)->JsResult<Value>{ORDER.with(|v|v.borrow_mut().push(b'T'));CALLS.with(|c|{let(t,b)=c.get();c.set((t+1,b))});let tables=rt.lookup(parent,"__nativeTables")?;let key=rt.string("Param");rt.get(tables,key)}
 fn battle(rt:&mut Runtime,this:Value,_:&[Value],_:EnvId)->JsResult<Value>{ORDER.with(|v|v.borrow_mut().push(b'B'));CALLS.with(|c|{let(t,b)=c.get();c.set((t,b+1))});let key=rt.string("battle_id");rt.get(this,key)}
 fn parser(_: &mut Runtime,_:Value,_:&[Value],_:EnvId)->JsResult<Value>{panic!("pure transient public parser should not execute in accepted outer fast path")}
 fn fixture()->Runtime{ORDER.with(|v|v.borrow_mut().clear());CALLS.with(|c|c.set((0,0)));let mut rt=Runtime::new();rt.native_battle_mode_limit_enabled=true;let ed=rt.object();let engine=rt.object();let cfg=rt.object();let mode=rt.string("stage");set(&mut rt,cfg,"mode",mode);set(&mut rt,engine,"config",cfg);set(&mut rt,engine,"battle_id",Value::Number(1.0));let id=rt.make_closure(battle,rt.global_env,0,"getBattleId");rt.set_function_source(id,&ID_SOURCE.encode_utf16().collect::<Vec<_>>()).unwrap();set(&mut rt,engine,"getBattleId",id);set(&mut rt,ed,"battleEngine",engine);let camps=rt.object();set(&mut rt,camps,"enemy",Value::Number(2.0));set(&mut rt,ed,"battle_camp",camps);let tf=rt.make_closure(table,rt.global_env,1,"getDataTable");rt.set_function_source(tf,&TABLE_SOURCE.encode_utf16().collect::<Vec<_>>()).unwrap();set(&mut rt,ed,"getDataTable",tf);let pf=rt.make_closure(parser,rt.global_env,1,"parseUseSkillCacheStageBattle");rt.set_function_source(pf,&PARSER_SOURCE.encode_utf16().collect::<Vec<_>>()).unwrap();set(&mut rt,ed,"parseUseSkillCacheStageBattle",pf);rt.declare(rt.global_env,"ed",ed).unwrap();let hero=rt.object();let info=rt.object();set(&mut rt,info,"ID",Value::Number(55.0));set(&mut rt,hero,"info",info);set(&mut rt,hero,"camp",Value::Number(2.0));rt.declare(rt.global_env,"hero",hero).unwrap();let stage=rt.object();let range=rt.object();let text=rt.string("stage;1;9000;tower;20001;29000");set(&mut rt,range,"StrValue",text);set(&mut rt,stage,"UseSkillCacheStageBattle",range);let heroes=rt.object();let text=rt.string("55;62;69");set(&mut rt,heroes,"StrValue",text);set(&mut rt,stage,"UseSkillCacheHeroList",heroes);rt.declare(rt.global_env,"rangeRow",range).unwrap();let param=rt.object();set(&mut rt,param,"Stage",stage);let tables=rt.object();set(&mut rt,tables,"Param",param);rt.declare(rt.global_env,"__nativeTables",tables).unwrap();rt}
 #[test]fn accepted_path_calls_both_actual_tables_and_conditional_battle_helper(){let mut rt=fixture();let hero=rt.lookup(rt.global_env,"hero").unwrap();assert_eq!(rt.try_native_battle_mode_limit(hero,rt.global_env).unwrap(),Some(Value::Bool(true)));assert_eq!(CALLS.with(|c|c.get()),(2,1));assert_eq!((rt.battle_mode_limit_attempts,rt.battle_mode_limit_hits),(1,1));let ed=rt.lookup(rt.global_env,"ed").unwrap();let engine=rt.mode_value(ed,"battleEngine").unwrap();let config=rt.mode_value(engine,"config").unwrap();let other=rt.string("other");set(&mut rt,config,"mode",other);CALLS.with(|c|c.set((0,0)));assert_eq!(rt.try_native_battle_mode_limit(hero,rt.global_env).unwrap(),Some(Value::Bool(false)));assert_eq!(CALLS.with(|c|c.get()),(2,0));}
 #[test]fn plan_rekeys_mutated_config_and_rejects_opaque_helpers_before_calls(){let mut rt=fixture();let hero=rt.lookup(rt.global_env,"hero").unwrap();assert_eq!(rt.try_native_battle_mode_limit(hero,rt.global_env).unwrap(),Some(Value::Bool(true)));let row=rt.lookup(rt.global_env,"rangeRow").unwrap();let text=rt.string("stage;2;3");set(&mut rt,row,"StrValue",text);assert_eq!(rt.try_native_battle_mode_limit(hero,rt.global_env).unwrap(),Some(Value::Bool(false)));let ed=rt.lookup(rt.global_env,"ed").unwrap();let opaque=rt.make_closure(table,rt.global_env,1,"opaque");set(&mut rt,ed,"getDataTable",opaque);CALLS.with(|c|c.set((0,0)));assert!(rt.try_native_battle_mode_limit(hero,rt.global_env).unwrap().is_none());assert_eq!(CALLS.with(|c|c.get()),(0,0));}
 #[test]fn rejected_noninteger_numbers_preserve_input_payloads_without_calls(){for bits in [0x7ff0000000000042,0xfff8000000001234,0x7ff0000000000000,0x3fe0000000000000]{let mut rt=fixture();let hero=rt.lookup(rt.global_env,"hero").unwrap();let info=rt.mode_value(hero,"info").unwrap();set(&mut rt,info,"ID",Value::Number(f64::from_bits(bits)));assert!(rt.try_native_battle_mode_limit(hero,rt.global_env).unwrap().is_none());let Value::Number(n)=rt.mode_value(info,"ID").unwrap()else{panic!()};assert_eq!(n.to_bits(),bits);assert_eq!(CALLS.with(|c|c.get()),(0,0));}}
 fn gc_rounds(rt:&mut Runtime,_:Value,_:&[Value],parent:EnvId)->JsResult<Value>{let env=rt.child_env(parent);for(name,n)in[("battles",23.0),("warmup",0.0),("battleIndex",0.0)]{rt.declare(env,name,Value::Number(n))?;}let hero=rt.lookup(parent,"hero")?;let mut seen=std::collections::HashSet::new();let mut reused=0;for i in 0..23{assert_eq!(rt.try_native_battle_mode_limit(hero,parent)?,Some(Value::Bool(true)));let transient=rt.object();let id=rt.object_id(transient)?;if seen.contains(&id){reused+=1}seen.insert(id);rt.assign(env,"battleIndex",Value::Number(i as f64),false)?;rt.collect_native_battle_backedge(env,parent)?;}assert!(reused>0);assert_eq!(CALLS.with(|c|c.get()),(46,23));Ok(Value::Number(rt.native_battle_gc_stats().collections as f64))}
 #[test]fn cached_config_and_guard_roots_survive_twenty_three_source_safepoints(){let mut rt=fixture();let f=rt.make_closure(gc_rounds,rt.global_env,0,"__nativeRun");rt.set_function_source(f,&include_str!("native_battle_run.js").encode_utf16().collect::<Vec<_>>()).unwrap();rt.enable_native_battle_gc();assert_eq!(rt.call(f,Value::Undefined,&[]).unwrap(),Value::Number(23.0));}

 fn engine_getter(rt:&mut Runtime,this:Value,_:&[Value],_:EnvId)->JsResult<Value>{ORDER.with(|v|v.borrow_mut().push(b'G'));let key=rt.string("_battleEngineInstance");rt.get(this,key)}
 fn forbidden_setter(_: &mut Runtime,_:Value,_:&[Value],_:EnvId)->JsResult<Value>{panic!("source predicate must never invoke engine setter")}
 fn install_engine_getter(rt:&mut Runtime)->(Value,Value){let ed=rt.lookup(rt.global_env,"ed").unwrap();let engine=rt.mode_value(ed,"battleEngine").unwrap();set(rt,ed,"_battleEngineInstance",engine);let key=rt.string("battleEngine");rt.delete(ed,key,true).unwrap();let get=rt.make_closure(engine_getter,rt.global_env,0,"get battleEngine");rt.set_function_source(get,&ENGINE_GETTER_SOURCE.encode_utf16().collect::<Vec<_>>()).unwrap();let setter=rt.make_closure(forbidden_setter,rt.global_env,1,"set battleEngine");rt.define_accessor(ed,key,Some(get),Some(setter),false,true).unwrap();(ed,engine)}
 #[test]fn warm_getter_is_actually_called_in_exact_source_order(){let mut rt=fixture();let(_,engine)=install_engine_getter(&mut rt);let hero=rt.lookup(rt.global_env,"hero").unwrap();assert_eq!(rt.try_native_battle_mode_limit(hero,rt.global_env).unwrap(),Some(Value::Bool(true)));assert_eq!(ORDER.with(|v|v.borrow().clone()),b"GGTGBT");assert_eq!(rt.battle_mode_limit_domain_hits,1);assert_eq!(rt.battle_mode_limit_getter_calls,3);let config=rt.mode_value(engine,"config").unwrap();let mode=rt.string("other");set(&mut rt,config,"mode",mode);ORDER.with(|v|v.borrow_mut().clear());assert_eq!(rt.try_native_battle_mode_limit(hero,rt.global_env).unwrap(),Some(Value::Bool(false)));assert_eq!(ORDER.with(|v|v.borrow().clone()),b"GGTT");assert_eq!(rt.battle_mode_limit_domain_hits,2);assert_eq!(rt.battle_mode_limit_getter_calls,5);}
 #[test]fn late_helper_poison_and_cold_instance_reject_before_any_getter(){for cold in[false,true]{let mut rt=fixture();let(ed,engine)=install_engine_getter(&mut rt);if cold{set(&mut rt,ed,"_battleEngineInstance",Value::Null)}else{let f=rt.make_closure(battle,rt.global_env,0,"opaque ID");set(&mut rt,engine,"getBattleId",f)}let hero=rt.lookup(rt.global_env,"hero").unwrap();assert!(rt.try_native_battle_mode_limit(hero,rt.global_env).unwrap().is_none());assert!(ORDER.with(|v|v.borrow().is_empty()));assert_eq!(rt.battle_mode_limit_getter_calls,0);assert_eq!(rt.battle_mode_limit_domain_hits,0);}}
 #[test]fn warm_accessor_identity_survives_actual_collections(){let mut rt=fixture();install_engine_getter(&mut rt);let f=rt.make_closure(gc_rounds,rt.global_env,0,"__nativeRun");rt.set_function_source(f,&include_str!("native_battle_run.js").encode_utf16().collect::<Vec<_>>()).unwrap();rt.enable_native_battle_gc();assert_eq!(rt.call(f,Value::Undefined,&[]).unwrap(),Value::Number(23.0));assert_eq!(rt.battle_mode_limit_domain_hits,23);assert_eq!(rt.battle_mode_limit_getter_calls,69);}
}
